# Explicit TEST-ONLY current diagnostic overlay, never SOURCE admission.
def source_current_cohort_read(root, relative, maximum=512 * 1024):
    part = Path(relative)
    if part.is_absolute() or '..' in part.parts or part.as_posix() != relative:
        raise ValueError('SOURCE_CURRENT_COHORT_PATH')
    file = root / part
    before = file.lstat()
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or before.st_size > maximum:
        raise ValueError('SOURCE_CURRENT_COHORT_REGULAR')
    with file.open('rb') as stream:
        opened = os.fstat(stream.fileno()); body = stream.read(maximum + 1); ended = os.fstat(stream.fileno())
    key = lambda row: (row.st_dev, row.st_ino, row.st_mode, row.st_nlink, row.st_size, row.st_mtime_ns, row.st_ctime_ns)
    if key(before) != key(opened) or key(opened) != key(ended) or key(ended) != key(file.lstat()) or len(body) != before.st_size:
        raise ValueError('SOURCE_CURRENT_COHORT_CHANGED')
    return body


def source_current_cohort_load(root, expected_sha, baseline_files):
    body = source_current_cohort_read(root, CURRENT_COHORT_DESCRIPTOR)
    if hashlib.sha256(body).hexdigest() != expected_sha:
        raise ValueError('SOURCE_CURRENT_COHORT_DESCRIPTOR')
    data = json.loads(body)
    if (data['kind'] != 'CURRENT_INSTRUMENTED_SOURCE_PROOF_HOST' or data['schemaVersion'] != 1
            or data['sourceAdmission'] is not False or data['productionActivation'] is not False
            or len(data['baselineProductPins']) != 27 or len(data['currentProductPins']) != 27
            or {row['path'] for row in data['products']} != {
                '.github/actions/save-owned-dmi-grib/index.cjs', 'scripts/run-owned-dmi-grib-save.py'}):
        raise ValueError('SOURCE_CURRENT_COHORT_SCOPE')
    digest = lambda value: hashlib.sha256(value).hexdigest()
    for name in ('baseline', 'current'):
        if digest(json.dumps(data[name + 'ProductPins'], separators=(',', ':')).encode()) != data[name + 'ProductIdentity']:
            raise ValueError('SOURCE_CURRENT_COHORT_PRODUCT_IDENTITY')
    for relative, pin in data['baselineProductPins'].items():
        if digest(baseline_files[relative]) != pin:
            raise ValueError('SOURCE_CURRENT_COHORT_BASELINE')
    replacements = []
    actual_pins = dict(data['baselineProductPins'])
    for row in data['products']:
        after = source_current_cohort_read(root, row['bankPath'])
        if len(after) != row['afterBytes'] or digest(after) != row['afterSha256'] or digest(baseline_files[row['path']]) != row['beforeSha256']:
            raise ValueError('SOURCE_CURRENT_COHORT_LEAF')
        inverse = after.decode('utf-8')
        for hunk in reversed(row['inverseHunks']):
            if inverse.count(hunk['after']) != hunk['count']:
                raise ValueError('SOURCE_CURRENT_COHORT_INVERSE')
            inverse = inverse.replace(hunk['after'], hunk['before'])
        if inverse.encode() != baseline_files[row['path']]:
            raise ValueError('SOURCE_CURRENT_COHORT_INVERSE')
        replacements.append((row, after))
        if row['path'] in actual_pins:
            actual_pins[row['path']] = row['afterSha256']
    if actual_pins != data['currentProductPins']:
        raise ValueError('SOURCE_CURRENT_COHORT_PRODUCT_IDENTITY')
    return data, replacements


def source_current_cohort_install(seed, originals, replacements):
    originals.mkdir()  # This new fixture owns exactly one absent namespace.
    for row, after in replacements:
        relative = row['path']; target = seed / relative
        before = source_current_cohort_read(seed, relative)
        if hashlib.sha256(before).hexdigest() != row['beforeSha256']:
            raise ValueError('SOURCE_CURRENT_COHORT_SEED_CHANGED')
        saved = originals / relative; saved.parent.mkdir(parents=True, exist_ok=True)
        with saved.open('xb') as stream:
            stream.write(before); stream.flush(); os.fsync(stream.fileno())
        staged = target.with_name(target.name + '.source-current-cohort-stage')
        with staged.open('xb') as stream:
            stream.write(after); stream.flush(); os.fsync(stream.fileno())
        if source_current_cohort_read(seed, relative) != before:
            raise ValueError('SOURCE_CURRENT_COHORT_SEED_CHANGED')
        os.replace(staged, target)
        if source_current_cohort_read(seed, relative) != after:
            raise ValueError('SOURCE_CURRENT_COHORT_SEED_CHANGED')


# Safe fixed observations only. None/UNKNOWN never becomes admission.
_COHORT_STAGES = frozenset(('UNKNOWN', 'PLATFORM', 'PARENT_GUARD', 'API_FD_GUARD',
    'PARENT_PIDFD', 'PARENT_LIVE', 'SIGNAL_SETUP', 'WORKER_SPAWN', 'WORKER_WAIT',
    'OWNED_GROUP_SIGNAL', 'GROUP_ABSENCE', 'SIGNAL_RESTORE', 'PARENT_FD_CLOSE',
    'API_FD_CLOSE', 'CLOSURE_WRITE'))
_COHORT_REASONS = frozenset(('UNKNOWN', 'OS_ERROR', 'DMI_RAW_SAVE_PLATFORM_REFUSED',
    'DMI_RAW_SAVE_PARENT_UNPROVED', 'DMI_RAW_SAVE_PARENT_LOST', 'DMI_RAW_SAVE_GROUP_UNPROVED',
    'DMI_RAW_SAVE_INTERRUPTED', 'DMI_RAW_SAVE_PARENT_FD_NOT_CLOSED', 'DMI_RAW_SAVE_PIPE_NOT_CLOSED'))
_COHORT_ERRNOS = frozenset(('NONE', 'UNKNOWN', 'ENOENT', 'ESRCH', 'EINTR', 'EIO',
    'EBADF', 'ECHILD', 'ENOMEM', 'EACCES', 'EINVAL', 'EMFILE', 'EPIPE'))
_COHORT_SIGNALS = frozenset(('NONE', 'UNKNOWN', 'SIGTERM', 'SIGKILL', 'SIGINT',
    'SIGPIPE', 'SIGABRT', 'SIGSEGV', 'SIGBUS', 'SIGHUP', 'SIGQUIT'))


def source_raw_cohort_observation(stderr):
    found = []
    for line in stderr.splitlines():
        match = re.fullmatch(r'DMI_RAW_SAVE_COHORT_OBSERVATION exit=(NONE|[0-9]{1,3}) signal=([A-Z_]+) stdout=([A-Z_]+) bytes=([0-9]{1,4}) stage=([A-Z_]+) reason=([A-Z_]+) errno=([A-Z_]+)', line)
        if match:
            exit_code, signal_name, stdout_class, count, stage, reason, number = match.groups()
            if ((exit_code == 'NONE' or int(exit_code) <= 255) and int(count) <= 4096
                    and signal_name in _COHORT_SIGNALS and stdout_class in ('EMPTY', 'INVALID_JSON', 'NON_OBJECT', 'OBJECT')
                    and stage in _COHORT_STAGES and reason in _COHORT_REASONS and number in _COHORT_ERRNOS):
                found.append({'exitCode': None if exit_code == 'NONE' else int(exit_code),
                    'signal': signal_name, 'stdoutClass': stdout_class, 'stdoutBytes': int(count),
                    'stage': stage, 'reason': reason, 'errno': number})
    return found[0] if len(found) == 1 else None


def source_disposition_observation(value, action_closed_ns):
    if type(value) is not dict:
        return None
    result = {'status': value.get('status') if value.get('status') in
        ('FAILED', 'STOP_UNPROVEN', 'DURABILITY_UNCONFIRMED') else 'UNKNOWN',
        'physicalStopProven': value.get('physicalStopProven') if type(value.get('physicalStopProven')) is bool else None,
        'localCipherSealed': value.get('localCipherSealed') if type(value.get('localCipherSealed')) is bool else None,
        'cloudFinalized': value.get('cloudFinalized') if type(value.get('cloudFinalized')) is bool else None,
        'clock': None, 'actionClosedNs': str(action_closed_ns)}
    clock = value.get('clock')
    if (type(clock) is dict and clock.get('kind') in ('PARENT_FIRST_FAILURE', 'CHILD_FIRST_FAILURE')
            and all(type(clock.get(key)) in (int, float) and 0 <= clock[key] <= 1e15
                    for key in ('caughtAt', 'cutoff'))):
        projected = {key: clock[key] for key in ('kind', 'caughtAt', 'cutoff')}
        projected['child'] = None
        if clock['kind'] == 'CHILD_FIRST_FAILURE':
            child = clock.get('child')
            if (type(child) is dict and type(child.get('reason')) is int and child['reason'] == 1
                    and all(type(child.get(key)) is str and re.fullmatch(r'[1-9][0-9]{0,29}', child[key])
                            for key in ('caughtNs', 'cutoffNs'))):
                projected['child'] = {key: child[key] for key in ('reason', 'caughtNs', 'cutoffNs')}
            else:
                return result
        result['clock'] = projected
    return result


def source_native_diagnostic_projection(stderr):
    result = {'sourceDiagnostic': None, 'rawSaveDiagnostic': None, 'firstSafeCode': 'UNKNOWN'}
    catalog = SOURCE_NATIVE_OBSERVER_CATALOG
    # Parse the already safe, existing CLI projections, not arbitrary error text
    # or the later unittest stderr. A generic FAIL can never become a reason.
    for line in stderr.splitlines():
        match = re.fullmatch(r'SOURCE_RUN_DIAGNOSTIC stage=([A-Z0-9_]+) reason=([A-Z0-9_]+) node_class=([A-Z0-9_]+) rejection=([A-Z0-9_]+)', line)
        if match and result['sourceDiagnostic'] is None:
            stage, reason, node_class, rejection = match.groups()
            if (stage in catalog['stages'] and reason in catalog['reasons']
                    and node_class in catalog['nodeClasses'] and rejection in catalog['rejections']):
                result['sourceDiagnostic'] = {'stage': stage, 'reason': reason, 'nodeClass': node_class, 'rejection': rejection}
        match = re.fullmatch(r'DMI_RAW_SAVE_DIAGNOSTIC stage=([A-Z0-9_]+) reason=([A-Z0-9_]+)', line)
        if match and result['rawSaveDiagnostic'] is None:
            stage, reason = match.groups()
            if stage in catalog['rawStages'] and reason in catalog['rawReasons']:
                result['rawSaveDiagnostic'] = {'stage': stage, 'reason': reason}
    for diagnostic in (result['sourceDiagnostic'], result['rawSaveDiagnostic']):
        if diagnostic is not None and diagnostic['reason'] != 'UNKNOWN':
            result['firstSafeCode'] = diagnostic['reason']
            break
    return result


