    def test_unissued_reason_is_not_admitted_by_source_prefix(self):
        value = self.project(b'SOURCE_RUN_DIAGNOSTIC stage=PRELUDE reason=SOURCE_INVENTED_UNISSUED_REASON node_class=ERROR rejection=NONE\n')
        self.assertIsNone(value['sourceDiagnostic'])
        self.assertEqual(value['firstSafeCode'], 'UNKNOWN')

    def test_unknown_code_projects_only_actual_qualified_module_frame(self):
        file = self.root / 'scripts/known.mjs'; file.parent.mkdir(); body = b'//one\nthrow new Error();\n'; file.write_bytes(body)
        row = {'relativePath': 'scripts/known.mjs', 'bytes': len(body), 'sha256': hashlib.sha256(body).hexdigest()}
        value = self.project(('Error: PRIVATE_SENTINEL\n    at hidden (' + file.as_uri() + ':2:3)\n').encode(), rows=[row])
        self.assertEqual(value['projectedFrames'], [{'module': 'scripts/known.mjs', 'sha256': row['sha256'], 'line': 2, 'column': 3, 'stream': 'stderr'}])
        self.assertNotIn(str(self.root), json.dumps(value)); self.assertNotIn('PRIVATE_SENTINEL', json.dumps(value))

    def test_external_frame_is_never_read_or_exposed(self):
        value = self.project(b'    at unknown (/etc/private-observer-sentinel:3:4)\n')
        self.assertEqual(value['projectedFrames'], []); self.assertEqual(value['unmappedFrames'], 1)
        self.assertNotIn('private-observer-sentinel', json.dumps(value))

    def test_changed_module_is_not_projected(self):
        file = self.root / 'known.py'; file.write_bytes(b'#changed\n')
        value = self.project(('  File "' + str(file) + '", line 1, in caller\n').encode(),
            rows=[{'relativePath': 'known.py', 'bytes': 9, 'sha256': '0' * 64}])
        self.assertEqual(value['projectedFrames'], []); self.assertEqual(value['unmappedFrames'], 1)

    def test_unclosed_action_is_not_reported_as_exit_or_stop_authority(self):
        value = self.project(exit_code=None)
        self.assertIsNone(value['actionExitCode'])
        self.assertFalse(value['rawLogsUploaded'])
        self.assertNotIn('physicalStopProven', value)

    def test_generic_closed_phase_keeps_reason_and_only_qualified_frames(self):
        file = self.root / 'phase-proof.mjs'
        body = b'// known source\nthrow new Error();\n'; file.write_bytes(body)
        row = {'relativePath': 'phase-proof.mjs', 'bytes': len(body), 'sha256': hashlib.sha256(body).hexdigest()}
        frame = '    at hidden (' + file.as_uri() + ':2:3)\n'
        for reason, expected in (('SOURCE_NORMAL_PHASE_FAILED', [
                {'module': row['relativePath'], 'sha256': row['sha256'], 'line': 2, 'column': 3, 'stream': 'stderr'}]),
                ('SOURCE_PRELUDE_PROGRAM_FAILED', [])):
            with self.subTest(reason=reason):
                line = 'SOURCE_RUN_DIAGNOSTIC stage=PRODUCER_CHAIN reason=' + reason + ' node_class=ERROR rejection=NONE\n'
                value = self.project((line + frame).encode(), rows=[row])
                self.assertEqual(value['firstSafeCode'], reason)
                self.assertEqual(value['projectedFrames'], expected)
                self.assertNotIn(str(self.root), json.dumps(value))
                self.assertNotIn('sourceCode', value)




    def test_permission_refusal_requires_actual_exited_pidfd_not_a_live_child(self):
        self.assertEqual(sys.platform, 'linux')
        # One local TEST-ONLY program, no provider/source/owner interception.
        body = "import ctypes,time\nlibc=ctypes.CDLL(None,use_errno=True)\nassert libc.prctl(4,0,0,0,0)==0\nprint('READY',flush=True)\ntime.sleep(60)\n"
        child = subprocess.Popen([sys.executable, '-I', '-B', '-c', body], stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        descriptor = None; first = None
        try:
            descriptor = os.pidfd_open(child.pid)
            ready = select.poll(); ready.register(child.stdout.fileno(), select.POLLIN)
            self.assertTrue(ready.poll(5000), 'LOCAL_UNDUMPABLE_CHILD_NOT_READY')
            self.assertEqual(child.stdout.readline(), b'READY\n')
            with self.assertRaises(PermissionError):
                source_terminal_producer_stdin(child.pid)
            signal.pidfd_send_signal(descriptor, signal.SIGKILL)
            ended = select.poll(); ended.register(descriptor, select.POLLIN)
            self.assertTrue(source_terminal_pidfd_exit_event(descriptor, ended.poll(5000), select.POLLIN, select.POLLHUP))
            # An exited discovery may already have lost its procfs fd link.
            try:
                zombie_stdin = source_terminal_producer_stdin(child.pid)
            except FileNotFoundError as error:
                self.assertEqual(error.errno, errno.ENOENT)
            else:
                self.assertIsNone(zombie_stdin)
            self.assertIsNone(child.returncode, 'Discovery must not reap or claim an action exit')
        except BaseException as error:
            first = error
            raise
        finally:
            try:
                if descriptor is not None:
                    try: signal.pidfd_send_signal(descriptor, signal.SIGKILL)
                    except ProcessLookupError: pass
                    os.close(descriptor)
                else:
                    child.kill()  # Standard Popen ownership/exit check, never a discovered PID.
                child.wait(timeout=5)
                child.stdout.close(); child.stderr.close()
            except BaseException:
                if first is None:
                    raise
                first.add_note('LOCAL_TEST_CHILD_CLEANUP_UNPROVED')


