            files = []
            for name in names:
                relative = Path(name)
                if relative.is_absolute() or '..' in relative.parts or not name.startswith('.cache/dmi-grib/' if role == 'raw' else cipher_path):
                    raise AssertionError('SOURCE_TERMINAL_SDK_ARCHIVE_PATH')
                if name.endswith('/'):
                    if role != 'raw':
                        raise AssertionError('SOURCE_TERMINAL_SDK_ARCHIVE_DIRECTORY')
                    continue
                file = self.working_root / relative
                info = file.lstat()
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                    raise AssertionError('SOURCE_TERMINAL_SDK_WORKING_FILE')
                extracted = subprocess.run(['tar', '-xOf', str(archive), name], stdin=subprocess.DEVNULL,
                    env=clean_environment(), capture_output=True, timeout=5, check=True)
                actual = file.read_bytes()
                if extracted.stderr or extracted.stdout != actual:
                    raise AssertionError('SOURCE_TERMINAL_SDK_ARCHIVED_BYTES_CHANGED')
                files.append({'path': name, 'bytes': len(actual), 'sha256': sha(actual)})
