def source_terminal_test_failure(error, phase):
    result = {'phase': phase if phase in SOURCE_TERMINAL_OBSERVER_PHASES else 'UNKNOWN', 'code': 'UNKNOWN'}
    try:
        value = str(error)
        codes = [code for code in SOURCE_TERMINAL_OBSERVER_CODES if code != 'UNKNOWN'
                 and (value == code or value.endswith(': ' + code))]
        if len(codes) == 1:
            result['code'] = codes[0]
    except BaseException:
        pass  # Observation can never replace the actual first exception.
    return result


def source_terminal_pidfd_exit_event(descriptor, events, readable, hungup):
    # Pure event decision, not process/SAVE authority. Only actual pidfd poll
    # output reaches this function in the native adapter below.
    return (type(descriptor) is int and descriptor >= 0 and type(events) is list and len(events) == 1
        and type(readable) is int and type(hungup) is int and readable > 0 and hungup > 0
        and readable & hungup == 0 and type(events[0]) is tuple and len(events[0]) == 2
        and type(events[0][0]) is int and events[0][0] == descriptor and type(events[0][1]) is int
        and events[0][1] in (readable, readable | hungup))


def source_terminal_producer_stdin(pid):
    # A fresh owned pidfd is retained across this one procfs read. A vanished
    # process is discovery only; no producer/finalizer/stall is counted here.
    descriptor = os.pidfd_open(pid)
    try:
        try:
            return os.readlink(f'/proc/{pid}/fd/0')
        except PermissionError:
            poller = select.poll(); poller.register(descriptor, select.POLLIN)
            if source_terminal_pidfd_exit_event(descriptor, poller.poll(0), select.POLLIN, select.POLLHUP):
                return None
            raise  # Live or unknown permission failure remains the SAME error.
    finally:
        os.close(descriptor)


