def source_terminal_exception_projection(error, phase, callsite=None):
    # Diagnostic only. Never copy a message, filename, class name or stack text.
    result = source_terminal_test_failure(error, phase)
    types = {AssertionError: 'ASSERTION_ERROR', FileNotFoundError: 'FILE_NOT_FOUND_ERROR',
        ProcessLookupError: 'PROCESS_LOOKUP_ERROR', PermissionError: 'PERMISSION_ERROR', OSError: 'OS_ERROR',
        json.JSONDecodeError: 'JSON_DECODE_ERROR', ValueError: 'VALUE_ERROR', TypeError: 'TYPE_ERROR',
        KeyError: 'KEY_ERROR', IndexError: 'INDEX_ERROR', RuntimeError: 'RUNTIME_ERROR', OverflowError: 'OVERFLOW_ERROR'}
    result.update(exceptionType=types.get(type(error), 'UNKNOWN'), osError='NONE', callsite=None)
    if type(error) in (FileNotFoundError, ProcessLookupError, PermissionError, OSError):
        name = errno.errorcode.get(error.errno) if type(error.errno) is int else None
        result['osError'] = name if name in SOURCE_TERMINAL_OS_ERRORS else 'UNKNOWN'
    if (type(callsite) is dict and set(callsite) == {'module', 'sha256', 'line'}
            and type(callsite['module']) is str and re.fullmatch(r'scripts/[A-Za-z0-9_/-]+\.py', callsite['module'])
            and '..' not in callsite['module'].split('/') and type(callsite['sha256']) is str
            and re.fullmatch(r'[a-f0-9]{64}', callsite['sha256'])
            and type(callsite['line']) is int and 1 <= callsite['line'] <= 1000000):
        result['callsite'] = dict(callsite)
    return result


