def source_terminal_first_transport_failure(previous, category, error=None, callsite=None):
    if previous is not None:
        return previous
    inner = None
    if error is not None:
        projected = source_terminal_exception_projection(error, 'SDK_AND_ORIGINALS', callsite)
        inner = {key: projected[key] for key in ('code', 'exceptionType', 'osError', 'callsite')}
        inner['code'] = 'UNKNOWN'
