def current_native_pg(context, sql, *, capture=None):
    """Actual SAME normal owned Unix-socket PostgreSQL, never an RPC fixture."""
    if (type(context) is not dict or set(context) != {'kind', 'pgRoot', 'psql', 'head', 'server'}
            or context['kind'] != 'SOURCE_CURRENT_SAME_NATIVE_PG'):
        raise ValueError('SOURCE_CURRENT_PROFILE_PG_CONTEXT')
    pg = Path(context['pgRoot'])
    executable = Path(context['psql'])
    if (not pg.is_absolute() or pg.resolve(strict=True) != pg or pg.parent != Path(tempfile.gettempdir()).resolve()
            or not pg.name.startswith('rr-checkpoint-pg-') or pg.is_symlink()
            or not executable.is_absolute() or not executable.is_file()):
        raise ValueError('SOURCE_CURRENT_PROFILE_OWN_PG_REQUIRED')
    pid = int((pg / 'database/postmaster.pid').read_text().splitlines()[0])
    socket = pg / 'socket'
    if socket.resolve(strict=True) != socket or socket.is_symlink() or not socket.is_dir():
        raise ValueError('SOURCE_CURRENT_PROFILE_SOCKET_CHANGED')
    birth = Path(f'/proc/{pid}/stat').read_text().rsplit(')', 1)[1].split()[19]
    argv = Path(f'/proc/{pid}/cmdline').read_bytes().split(b'\0')
    if context['server'] != {'pid': pid, 'birth': birth} or os.fsencode(pg / 'database') not in argv:
        raise ValueError('SOURCE_CURRENT_PROFILE_PG_OWNER_CHANGED')
    environment = clean_environment()
    environment.update(PGHOST=str(pg / 'socket'), PGPORT='5432', PGDATABASE='postgres',
        PGUSER='rr_native_test', PGSSLMODE='disable', PGPASSFILE=str(pg / 'absent-password-file'))
    capture_files = None
    if capture is not None:
        # Test-only optional retention for EXACTLY the two legacy payload
        # reads; all old/default/CURRENT callers retain their former behavior.
        if (CASE != 'source-legacy-compatibility' or type(capture) is not tuple or len(capture) != 2
                or capture[1] not in ('current', 'follower')):
            raise ValueError('SOURCE_LEGACY_SQL_CAPTURE_SCOPE')
        parent, role = Path(capture[0]), capture[1]
        if (not parent.is_absolute() or parent.resolve(strict=True) != parent or not parent.is_dir()
                or parent.parent != Path(tempfile.gettempdir()).resolve()
                or not parent.name.startswith('rr-source19-union-native-')):
            raise ValueError('SOURCE_LEGACY_SQL_CAPTURE_OWNER')
        capture_files = tuple(parent / ('legacy-' + role + '-sql-whole.' + stream) for stream in ('stdout', 'stderr'))
    result = subprocess.run([str(executable), '-X', '-qAt', '-v', 'ON_ERROR_STOP=1', '-v', 'VERBOSITY=sqlstate',
        '-h', str(pg / 'socket'), '-p', '5432', '-U', 'rr_native_test', '-d', 'postgres'],
        input=sql.encode('utf8'), env=environment, capture_output=True, check=False, timeout=70)
    if capture_files is not None:
        # Exact bytes BEFORE return-code/bound/SQLSTATE selection. A failed
        # SQL read cannot print a successful result or overwrite prior logs.
        for file, body in zip(capture_files, (result.stdout, result.stderr), strict=True):
            with file.open('xb') as stream:
                stream.write(body); stream.flush(); os.fsync(stream.fileno())
    if result.returncode or len(result.stdout) > 16 * 1024 * 1024:
        # Raw SQL, payloads and stderr remain private; preserve the first failure.
        error = ValueError('SOURCE_CURRENT_PROFILE_ACTUAL_PG_CALL_FAILED')
        found = re.search(rb'(?:^|\n)[^\r\n]*\b(?:ERROR|FATAL):[ \t]+([A-Z0-9]{5})[ \t]*\r?(?:\n|$)', result.stderr[:16384])
        current_native_post64_module().emit_current_native_failure(error, phase='PG_SQL',
            sqlstate=found.group(1).decode('ascii') if found else 'UNKNOWN')
        raise error
    return result.stdout.decode('utf8').strip()


def current_native_pg_capture(context):
    # Missing full normal schema/central activation is an explicit prerequisite,
    # not permission to author READY/profile rows or copy an old protocol.json.
    signature = 'public.ravradar_integrated_cutover_contract(' + ','.join(['text'] * 22) + ')'
    available = json.loads(current_native_pg(context, "select jsonb_build_object("
        "'integrated',to_regprocedure('" + signature + "') is not null,"
        "'checkpoint',to_regprocedure('public.ravradar_ravscore_checkpoint_contract()') is not null);"))
    if available != {'integrated': True, 'checkpoint': True}:
        raise ValueError('SOURCE_CURRENT_PROFILE_PENDING_FULL_PG_SCHEMA')
    request = subprocess.run([str(NODE), str(ROOT / 'scripts/fixtures/source19-current-native-metadata.mjs'), '--rpc-request'],
        cwd=ROOT, env=clean_environment(), stdin=subprocess.DEVNULL, capture_output=True, check=True, timeout=30)
    body = json.loads(request.stdout)['integratedRequestBody']
    if len(body) != 22 or any(not re.fullmatch(r'p_[a-z0-9_]+', key) or type(value) is not str for key, value in body.items()):
        raise ValueError('SOURCE_CURRENT_PROFILE_NORMAL_RPC_REQUEST')
    call = 'public.ravradar_integrated_cutover_contract(' + ','.join(key + "=>'" + value.replace("'", "''") + "'" for key, value in body.items()) + ')'
    actual = json.loads(current_native_pg(context, "select jsonb_build_object("
        "'integrated'," + call + ","
        "'checkpoint',public.ravradar_ravscore_checkpoint_contract(),"
        "'admin',(select coalesce(jsonb_agg(to_jsonb(a) order by document_key),'[]'::jsonb)"
        " from public.admin_documents a where document_key not in"
        " ('ravscore-private-production-runtime-pointer','ravscore-continuation-checkpoint')));"))
    rows = {row['document_key']: row for row in actual['admin']}
    if not {'ravscore-operational-model-activation', 'ravscore-profile-selection'} <= set(rows):
        raise ValueError('SOURCE_CURRENT_PROFILE_PENDING_GENUINE_CENTRAL_PROFILE')
    actual['rpcBody'] = body
    return actual


def current_native_json_literal(value):
    # Data-only SQL literal; no caller SQL identifiers or commands are accepted.
    return "convert_from(decode('" + __import__('base64').b64encode(
        json.dumps(value, separators=(',', ':'), allow_nan=False).encode()).decode() + "','base64'),'UTF8')::jsonb"


